function validateSignMode(value, defaultValue) {
  // 无值则为空串
  if ([null, undefined].includes(value)) {
    value = defaultValue
  }

  // 转成枚举常量比较
  value = value.toUpperCase()

  let ret = value

  if (!compileOptionsMeta.signModeEnum[value]) {
    ret = defaultValue
    colorconsole.warn(`当前signMode参数不支持: ${value} ，改为默认值：${ret}`)
  }
  return ret
}

/**
 * 校验SplitChunkMode参数的有效值
 * @param value {string}
 * @return {string}
 */
function validateSplitChunksMode(value) {
  // 转成枚举常量比较
  value = value.toUpperCase()

  let ret = value

  if (!compileOptionsMeta.splitChunksModeEnum[value]) {
    ret = compileOptionsMeta.splitChunksModeEnum.REDUNDANCY
    colorconsole.warn(`当前splitChunksMode参数不支持: ${value} ，改为默认值：${ret}`)
  }
  return ret
}

/**
 * 校验buildNameFormat参数的有效值
 * @param value {string}
 * @return {string}
 */
function validateBuildNameFormat(value) {
  let ret = value.toUpperCase()
  const reg = /(^custom=)(.*)/i
  if (!compileOptionsMeta.buildNameFormat[ret]) {
    ret = value.replace(reg, 'CUSTOM=$2')
  }

  if (
    (!compileOptionsMeta.buildNameFormat[ret] && !ret.startsWith('CUSTOM=')) ||
    ret === 'CUSTOM='
  ) {
    if (ret.startsWith('CUSTOM')) {
      colorconsole.warn(
        `当前buildNameFormat参数不支持: ${value} ，请添加自定义custom值，改为默认值：${compileOptionsMeta.buildNameFormat.DEFAULT}`
      )
    } else {
      colorconsole.warn(
        `当前buildNameFormat参数不支持: ${value} ，改为默认值：${compileOptionsMeta.buildNameFormat.DEFAULT}`
      )
    }
    ret = compileOptionsMeta.buildNameFormat.DEFAULT
  }
  return ret
}

